package net.ludovicoflaviano.bettersfp.data;
import org.bukkit.*;import org.bukkit.configuration.ConfigurationSection;import org.bukkit.plugin.java.JavaPlugin;import java.io.File;import java.nio.file.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
public final class SpawnerStore {
 private final JavaPlugin plugin;private final Map<String,SpawnerData> data=new ConcurrentHashMap<>();public SpawnerStore(JavaPlugin p){plugin=p;}public Map<String,SpawnerData> all(){return data;}public SpawnerData get(Location l){return data.get(key(l));}public void put(Location l,SpawnerData d){data.put(key(l),d);}public void remove(Location l){data.remove(key(l));}
 public static String key(Location l){return l.getWorld().getUID()+":"+l.getBlockX()+":"+l.getBlockY()+":"+l.getBlockZ();}
 public static Location location(String k){try{String[] p=k.split(":");World w=Bukkit.getWorld(UUID.fromString(p[0]));return w==null?null:new Location(w,Integer.parseInt(p[1]),Integer.parseInt(p[2]),Integer.parseInt(p[3]));}catch(Exception e){return null;}}
 public void load(){data.clear();File f=new File(plugin.getDataFolder(),"spawners.yml");if(!f.exists())return;var y=new org.bukkit.configuration.file.YamlConfiguration();try{y.load(f);}catch(Exception e){plugin.getLogger().severe("Load failed: "+e.getMessage());return;}ConfigurationSection r=y.getConfigurationSection("spawners");if(r==null)return;for(String k:r.getKeys(false)){ConfigurationSection x=r.getConfigurationSection(k);if(x==null)continue;try{SpawnerData d=new SpawnerData(k,UUID.fromString(x.getString("owner")),x.getString("entity","ZOMBIE"));d.stack=x.getInt("stack",1);d.speedLevel=x.getInt("speed",0);d.yieldLevel=x.getInt("yield",0);d.storageLevel=x.getInt("storage",0);d.storedXp=x.getLong("xp",0);ConfigurationSection it=x.getConfigurationSection("items");if(it!=null)for(String m:it.getKeys(false))try{d.items.put(Material.valueOf(m),it.getInt(m));}catch(Exception ignored){}data.put(k,d);}catch(Exception ignored){}}}
 public synchronized void save(){var y=new org.bukkit.configuration.file.YamlConfiguration();ConfigurationSection r=y.createSection("spawners");for(SpawnerData d:data.values()){ConfigurationSection x=r.createSection(d.key);x.set("owner",d.owner.toString());x.set("entity",d.entity);x.set("stack",d.stack);x.set("speed",d.speedLevel);x.set("yield",d.yieldLevel);x.set("storage",d.storageLevel);x.set("xp",d.storedXp);ConfigurationSection it=x.createSection("items");for(var e:d.items.entrySet())it.set(e.getKey().name(),e.getValue());}try{File f=new File(plugin.getDataFolder(),"spawners.yml"),t=new File(plugin.getDataFolder(),"spawners.yml.tmp");f.getParentFile().mkdirs();y.save(t);try{Files.move(t.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(t.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING);}}catch(Exception e){plugin.getLogger().severe("Save failed: "+e.getMessage());}}
}
